}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem 0;
    border: 1px solid #dee2e6;
}

.sidebar-title {
