    margin: 0;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1rem;
    border-left: 3px solid transparent;
    border-radius: 0;
    cursor: pointer;
    transition: background-color 0.15s, border-color 0.15s;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border-top: none;
    border-right: none;
    border-bottom: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    border-left-color: #0d6efd;
    color: #0d6efd;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
}

/* Avatar */
.avatar-preview {
    padding: 1rem;
}

.avatar-preview img {
    border: 3px solid #dee2e6;
    object-fit: cover;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s;
}

.appearance-preview .preview-header {
    padding: var(--preview-padding, 1rem);
    border-bottom: 1px solid #dee2e6;
}

.appearance-preview .preview-body {
    padding: var(--preview-padding, 1rem);
}

.appearance-preview .preview-footer {
    padding: var(--preview-padding, 1rem);
    border-top: 1px solid #dee2e6;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-dark {
    background: #212529;
    color: #e9ecef;
    border-color: #495057;
}

.preview-dark .preview-header {
    background: #2c3034;
    border-color: #495057;
}

.preview-dark .preview-body {
    border-color: #495057;
}

.preview-dark .preview-footer {
    border-color: #495057;
}

/* Modal backdrop fix */
.modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 1040;
    background-color: rgba(0, 0, 0, 0.5);
}

.modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    overflow-y: auto;
}
