toolArgs.file_text:
@using sv_44a9b3603be34eda94857f96b1842565.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>
    <hr />

    @if (_loading)
    {
        <p>Loading appearance settings…</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = string.Empty"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <!-- Theme -->
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-6">
                <h5>Preview</h5>
                <div class="appearance-preview @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                    <div class="preview-header">
                        <strong>Sample Header</strong>
                    </div>
                    <div class="preview-body">
                        <p style="margin-bottom: 0.5rem;">This is a preview of your selected appearance settings.</p>
                        <p style="margin-bottom: 0.5rem;">Theme: <strong>@_theme</strong></p>
                        <p style="margin-bottom: 0.5rem;">Font size: <strong>@_fontSize</strong></p>
                        <p style="margin-bottom: 0.5rem;">Language: <strong>@_language</strong></p>
                        @if (_compactMode)
                        {
                            <span class="badge bg-info">Compact</span>
                        }
                    </div>
                    <div class="preview-footer">
                        <button class="btn btn-sm btn-primary" disabled>Sample Button</button>
                        <button class="btn btn-sm btn-outline-secondary ms-1" disabled>Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string _message = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewThemeClass() => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string GetPreviewStyle()
    {
        var fs = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = _compactMode ? "0.5rem" : "1rem";
        return $"font-size: {fs}; --preview-padding: {padding};";
    }
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="s => _activeSection = s" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

.settings-dashboard {
    display: flex;
    gap: 1.5rem;
    min-height: 70vh;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem 0;
    border: 1px solid #dee2e6;
}

.sidebar-title {
    padding: 0 1rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1rem;
    border-left: 3px solid transparent;
    border-radius: 0;
    cursor: pointer;
    transition: background-color 0.15s, border-color 0.15s;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border-top: none;
    border-right: none;
    border-bottom: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    border-left-color: #0d6efd;
    color: #0d6efd;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
}

/* Avatar */
.avatar-preview {
    padding: 1rem;
}

.avatar-preview img {
    border: 3px solid #dee2e6;
    object-fit: cover;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s;
}

.appearance-preview .preview-header {
    padding: var(--preview-padding, 1rem);
    border-bottom: 1px solid #dee2e6;
}

.appearance-preview .preview-body {
    padding: var(--preview-padding, 1rem);
}

.appearance-preview .preview-footer {
    padding: var(--preview-padding, 1rem);
    border-top: 1px solid #dee2e6;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-dark {
    background: #212529;
    color: #e9ecef;
    border-color: #495057;
}

.preview-dark .preview-header {
    background: #2c3034;
    border-color: #495057;
}

.preview-dark .preview-body {
    border-color: #495057;
}

.preview-dark .preview-footer {
    border-color: #495057;
}

/* Modal backdrop fix */
.modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 1040;
    background-color: rgba(0, 0, 0, 0.5);
}

.modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    overflow-y: auto;
}

