+    border-radius: 0.5rem;
+    overflow: hidden;
+    transition: all 0.2s;
+}
+
+.appearance-preview .preview-header {
+    padding: var(--preview-padding, 1rem);
+    border-bottom: 1px solid #dee2e6;
+}
+
+.appearance-preview .preview-body {
+    padding: var(--preview-padding, 1rem);
+}
+
+.appearance-preview .preview-footer {
+    padding: var(--preview-padding, 1rem);
+    border-top: 1px solid #dee2e6;
+}
+
+.preview-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-light .preview-header {
+    background: #f8f9fa;
+}
+
+.preview-dark {
+    background: #212529;
+    color: #e9ecef;
+    border-color: #495057;
+}
+
+.preview-dark .preview-header {
+    background: #2c3034;
+    border-color: #495057;
+}
+
+.preview-dark .preview-body {
+    border-color: #495057;
+}
+
+.preview-dark .preview-footer {
+    border-color: #495057;
+}
+
+/* Modal backdrop fix */
+.modal-backdrop {
+    position: fixed;
+    inset: 0;
+    z-index: 1040;
+    background-color: rgba(0, 0, 0, 0.5);
+}
+
+.modal.d-block {
+    position: fixed;
+    inset: 0;
+    z-index: 1050;
+    overflow-y: auto;
+}
+

